script:
frappe.ui.form.on("Leave Application", {
    onload_post_render(frm) {
        const is_hr =
            frappe.session.user === "Administrator" ||
            ["HR User", "HR Manager", "System Manager"]
                .some(role => frappe.user.has_role(role));

        if (is_hr) return;

        const hr_only_types = [
            "Mateřská dovolená",
            "Otcovská dovolená",
            "Rodičovská dovolená",
            "Překážka na straně zaměstnavatele",
            "Jiná překážka"
        ];

        const field = frm.fields_dict.leave_type;

        const apply_filter = () => {
            const original = field.get_query;

            if (!original || original._verisoft_wrapped) {
                return;
            }

            const wrapped = function() {
                const result = original.call(this) || {};

                return {
                    ...result,
                    filters: [
                        ...(result.filters || []),
                        [
                            "leave_type_name",
                            "not in",
                            hr_only_types
                        ]
                    ]
                };
            };

            wrapped._verisoft_wrapped = true;
            field.get_query = wrapped;
        };

        // Apply filter whenever the user interacts with the field.
        field.$input
            .off(".verisoft_leave")
            .on(
                "mousedown.verisoft_leave focusin.verisoft_leave",
                apply_filter
            );

        apply_filter();
    }
});

frappe.ui.form.on("Employee Data Change Request", {
    onload(frm) {
        if (!frm.is_new()) return;
        return frappe.call({
            method: "verisoft_hr.employee_data_change_request.get_request_defaults",
            args: {employee: frm.doc.employee || undefined},
        }).then(async (r) => {
            if (!r.message) return;
            frm.doc.__onload = frm.doc.__onload || {};
            frm.doc.__onload.verisoft_request_bank_access = r.message.bank_access;
            await frm.set_value(r.message.values);
            frm.trigger("refresh");
        });
    },
    refresh(frm) {
        // Values are protected on the server. Desk needs the per-document flags.
        const access = frm.doc.__onload?.verisoft_request_bank_access;
        frm.perm[1] = {
            ...(frm.perm[1] || {}),
            read: access?.read === 1 ? 1 : 0,
            write: access?.write === 1 && !frm.read_only && frm.perm[0]?.write ? 1 : 0,
        };
        frm.refresh_fields();
    },
});
